function buildBlocks() {
  blocks = [];
  const rows = LEVELS[level];
  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < COLS; c++) {
      const ch = rows[r][c];
      if (ch === '.') continue;
      const hp = Number(ch);
      blocks.push({
        x: MARGIN + c * CELL_W,
        y: TOP + r * CELL_H,
        w: CELL_W, h: CELL_H,
        hp, maxHp: hp,
      });
    }
